CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calls(id TEXT PRIMARY KEY, caller TEXT, created INTEGER NOT NULL,updated INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'New' CHECK(status IN ('New','Contacted','Closed')), outcome TEXT NOT NULL DEFAULT 'in-progress', consent TEXT NOT NULL DEFAULT 'pending',intake TEXT NOT NULL DEFAULT '{}',finalized INTEGER NOT NULL DEFAULT 0,urgent_sent INTEGER NOT NULL DEFAULT 0,summary TEXT NOT NULL DEFAULT '', prompt_version TEXT NOT NULL DEFAULT '1',ai_started INTEGER, ai_seconds INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,call_id TEXT NOT NULL REFERENCES calls(id) ON DELETE CASCADE,kind TEXT NOT NULL,recipient INTEGER NOT NULL CHECK(recipient IN(0,1)),destination TEXT NOT NULL,body TEXT NOT NULL,segments INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL,provider_id TEXT UNIQUE,error TEXT,updated INTEGER NOT NULL, UNIQUE(call_id,kind,recipient));
CREATE TABLE IF NOT EXISTS delivery_events(id TEXT PRIMARY KEY,outbox_id TEXT NOT NULL REFERENCES outbox(id) ON DELETE CASCADE,provider_id TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,event TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS outbox_due ON outbox(state,next_attempt);
CREATE INDEX IF NOT EXISTS calls_created ON calls(created);
CREATE TABLE IF NOT EXISTS session_store(id TEXT PRIMARY KEY,json TEXT NOT NULL,expires INTEGER NOT NULL);
